#include <stdio.h>
#include <string.h>

/* 把 tail 接在 bowl 屁股后面，答：接完之后整串有几颗珠子 */
int join_and_count(char bowl[], const char tail[]) {
    strcat(bowl, tail);
    return (int)strlen(bowl);
}

int main(void) {
    char bowl[64] = "{w1}";
    char tail[] = "{w2}";

    int n = join_and_count(bowl, tail);
    printf("接起来：%s，现在 %d 颗\n", bowl, n);
    return 0;
}
